{
  "summary": "Electrical system in a 2024 Ford Ranger Lariat randomly changes drive modes from Normal/Eco to Sand and 2WD to 4WD Lo/High, locking the differential, at idle, cold start, and highway speeds.",
  "group": "ELECTRICAL SYSTEM",
  "symptoms": [
    "changes driving modes on its own",
    "shifts from Normal or Eco to Sand",
    "shifts from 2WD to 4WD low or 4WD high",
    "locks the differential and compromises steering",
    "no warning lamps except a message that it cannot go into 4LO unless stopped"
  ],
  "conditions": [
    "cold",
    "intermittent"
  ],
  "fault_codes": [],
  "safety_relevant": true,
  "missing_info": [
    "mileage"
  ],
  "clues": [
    {
      "kind": "component_group",
      "quote": "ELECTRICAL SYSTEM"
    },
    {
      "kind": "symptom",
      "quote": "it has changed driving modes 15-20 times ON ITS OWN"
    },
    {
      "kind": "symptom",
      "quote": "It goes from NORMAL OR ECO all the way to SAND, from 2wd to 4wd lo if I am stopped or 4wd high"
    },
    {
      "kind": "symptom",
      "quote": "It also locks the differential so steering is somewhat compromised."
    },
    {
      "kind": "condition",
      "quote": "The truck has changed modes while Idling, at a cold start, and at driving speeds."
    },
    {
      "kind": "condition",
      "quote": "it is very random"
    },
    {
      "kind": "condition",
      "quote": "when I at at highway speeds."
    },
    {
      "kind": "safety",
      "quote": "If this thing decides to overrule the speed requirements for shifting to 4lo on the freeway, this would put others at risk."
    },
    {
      "kind": "other",
      "quote": "the dealer says they could not replicate the problem"
    },
    {
      "kind": "other",
      "quote": "they found no trouble codes"
    },
    {
      "kind": "symptom",
      "quote": "No warning lamps appear other than the message that it cannot go into 4lo unless I stop."
    },
    {
      "kind": "other",
      "quote": "replaced the selector switch, (ATCM)"
    }
  ]
}

